#include <print>

#define QUAD(x) ((x) * 4)
#define RAWQUAD(x) x * 4

int main() {
    std::println("QUAD(1 + 1) = {}", QUAD(1 + 1));
    std::println("RAWQUAD(1 + 1) = {}", RAWQUAD(1 + 1));
    return 0;
}
// 用 g++ -std=c++23 -E mac.cpp 看展开成品，两行分别是 ((1 + 1) * 4) 和 1 + 1 * 4

